// Format the error payload n8n hands to error workflows.
const data = $json;
const wf  = data.workflow  || {};
const ex  = data.execution || {};
const err = ex.error       || {};

// Markdown-escape user-supplied strings so * _ ` [ ] don't break formatting
const esc = (s) => String(s ?? '').replace(/[*_`\[\]]/g, m => '\\' + m);

const lines = [
  '🚨 *Workflow Failure*',
  '',
  `*Workflow:* ${esc(wf.name || 'unknown')}`,
  `*Failed at:* ${esc(ex.lastNodeExecuted || '(unknown node)')}`,
  `*Error:* ${esc(err.message || 'no message')}`
];

if (err.description) {
  lines.push(`*Detail:* ${esc(err.description)}`);
}

if (ex.url) {
  lines.push('', `[View execution](${ex.url})`);
}

const text = lines.join('\n');

return [{
  json: {
    text,
    workflow_name: wf.name || 'unknown',
    workflow_id:   wf.id   || null,
    execution_id:  ex.id   || null,
    failed_node:   ex.lastNodeExecuted || null,
    error_message: err.message || null
  }
}];
